#[test]
fn ipns_record_creation() {
    let private_key = hex::decode(ED25519_TEST_PRIVATE_KEY).unwrap();
    let pk: [u8; 32] = private_key.try_into().unwrap();

    let record = ipns::create_ipns_record(
