        86400000,
    )
    .unwrap();

    assert_eq!(
        record.value,
        "/ipfs/REDACTED"
    );
    assert_eq!(record.sequence, 42);
    assert_eq!(record.validity_type, 0);
    assert_eq!(record.signature_v1.len(), 64);
    assert_eq!(record.signature_v2.len(), 64);
    assert!(!record.data.is_empty());
    assert_eq!(record.public_key.len(), 32);
}

